previewCss:
.darma-loader-darma-b15-otp-code-fill { --accent: var(--loader-color, #4f46e5); --accent-2: var(--loader-secondary-color, #a5b4fc); width: var(--loader-size, 132px); height: calc(var(--loader-size, 132px) * .34); position: relative; display: flex; gap: 4%; align-items: stretch; }
.darma-loader-darma-b15-otp-code-fill span { position: relative; flex: 1; border-radius: 8px; box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 35%, transparent); animation: darma-loader-darma-b15-otp-code-fill-otp-box calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b15-otp-code-fill span::after { content: ''; position: absolute; left: 30%; right: 30%; top: 38%; height: 24%; border-radius: 50%; background: var(--accent); transform: scale(0); animation: darma-loader-darma-b15-otp-code-fill-otp-dot calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.3, 1.5, .5, 1) infinite; }
.darma-loader-darma-b15-otp-code-fill span:nth-of-type(2), .darma-loader-darma-b15-otp-code-fill span:nth-of-type(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .22); }
.darma-loader-darma-b15-otp-code-fill span:nth-of-type(3), .darma-loader-darma-b15-otp-code-fill span:nth-of-type(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b15-otp-code-fill span:nth-of-type(4), .darma-loader-darma-b15-otp-code-fill span:nth-of-type(4)::after { animation-delay: calc(var(--loader-speed, 1s) * .66); }
@keyframes darma-loader-darma-b15-otp-code-fill-otp-dot { 0%, 10% { transform: scale(0); } 26%, 74% { transform: scale(1); } 90%, 100% { transform: scale(0); } }
@keyframes darma-loader-darma-b15-otp-code-fill-otp-box { 0%, 10% { box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 30%, transparent); } 26%, 74% { box-shadow: inset 0 0 0 2px var(--accent-2); } 90%, 100% { box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 30%, transparent); } }

